# -*- coding: utf-8 -*-
"""Desktop UI localization — Core-40 source coverage, includes Persian RTL text.

This module is bundled as Python source in packaged desktop apps; it does not
require runtime network requests or separate data resource bundling.
"""
import locale
import os
import subprocess
import sys

SUPPORTED = ("en", "ru", "es", "fr", "de", "pt-BR", "pt-PT", "it", "ja", "ko", "fa", "nl", "id", "tr", "zh-Hans", "zh-Hant", "hi", "ar", "vi", "pl", "th", "ur", "bn", "pa", "ta", "te", "mr", "gu", "kn", "ml", "uz", "ms", "fil", "sw", "ro", "hu", "cs", "sk", "el", "he")


def normalize(code):
    code = (code or "").replace("_", "-").lower()
    if code in ("zh", "zh-cn", "zh-sg") or code.startswith("zh-hans"):
        return "zh-Hans"
    if code in ("zh-tw", "zh-hk", "zh-mo") or code.startswith("zh-hant"):
        return "zh-Hant"
    if code == "pt" or code.startswith("pt-pt"):
        return "pt-PT"
    if code.startswith("pt-br"):
        return "pt-BR"
    if code.startswith("uz-cyrl"):
        return None
    for lang in ("en", "ru", "es", "fr", "de", "it", "ja", "ko", "fa", "nl", "id", "tr", "hi", "ar", "vi", "pl", "th", "ur", "bn", "pa", "ta", "te", "mr", "gu", "kn", "ml", "uz", "ms", "fil", "sw", "ro", "hu", "cs", "sk", "el", "he"):
        if code == lang or code.startswith(lang + "-"):
            return lang
    return None


def selected_language():
    override = os.environ.get("APL_UI_LANGUAGE")
    if override and normalize(override):
        return normalize(override)
    # macOS GUI applications frequently inherit LANG=en_US even when the
    # per-user AppleLanguages order is different. Prefer actual OS UI language.
    if sys.platform == "darwin":
        try:
            result = subprocess.run(
                ["/usr/bin/defaults", "read", "-g", "AppleLanguages"],
                capture_output=True, text=True, timeout=2, check=False,
            )
            if result.returncode == 0:
                for item in result.stdout.splitlines():
                    value = normalize(item.strip().strip(',').strip('"'))
                    if value:
                        return value
        except (OSError, subprocess.SubprocessError):
            pass
    candidates = [os.environ.get("LC_ALL"), os.environ.get("LC_MESSAGES"),
                  os.environ.get("LANGUAGE"), os.environ.get("LANG")]
    try:
        candidates.append(locale.getlocale()[0])
    except Exception:
        pass
    for item in candidates:
        if item:
            result = normalize(item.split(":", 1)[0].split(".", 1)[0])
            if result:
                return result
    return "en"


LANGUAGE = selected_language()


def tr(text):
    return CATALOGS.get(LANGUAGE, CATALOGS["en"]).get(text, text)


